avatar-group.example:
---
import AvatarGroup from '@/components/ui/data-display/AvatarGroup/AvatarGroup.astro';
---

<AvatarGroup
  max={3}
  avatars={[
    { src: '/avatars/ada.jpg', alt: 'Ada Lovelace' },
    { alt: 'Grace Hopper' },
    { fallback: 'AT' },
    { alt: 'Alan Kay' },
  ]}
/>

table.example:
---
import Table from '@/components/ui/data-display/Table/Table.astro';
---

<Table
  striped
  columns={[
    { key: 'plan', label: 'Plan' },
    { key: 'price', label: 'Price', align: 'right' },
  ]}
  rows={[
    { plan: 'Starter', price: '$0' },
    { plan: 'Pro', price: '$29' },
  ]}
/>

